<?php require 'config.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: feedback.html');exit;}verify_csrf();$name=trim($_POST['studentname']??'');$email=trim($_POST['email']??'');$cat=trim($_POST['category']??'');$rating=trim($_POST['rating']??'Average');$feedback=trim($_POST['feedback']??'');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$cat||!$feedback){exit('Please fill all feedback fields. <a href="feedback.html">Back</a>');}$uid=$_SESSION['user']['id']??null;$q=$pdo->prepare('INSERT INTO feedback(user_id,student_name,email,category,rating,feedback) VALUES(?,?,?,?,?,?)');$q->execute([$uid,$name,$email,$cat,$rating,$feedback]);header('Location: feedback.html?submitted=1');exit;?>